def transform(grid):
    """Restore interrupted straight strokes in the single-color line drawing."""
    out = [row[:] for row in grid]
    flat = [v for row in grid for v in row]
    bg = max(set(flat), key=flat.count)
    marks = {v for v in flat if v != bg}
    if len(marks) != 1:
        return out
    mark = next(iter(marks))
    h, w = len(grid), len(grid[0])
    coords = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == mark]
    rmin = min(r for r, c in coords)
    rmax = max(r for r, c in coords)
    cmin = min(c for r, c in coords)
    cmax = max(c for r, c in coords)

    # Complete the outside rectangular contour, including long erased runs.
    for c in range(cmin, cmax + 1):
        for r in (rmin, rmax):
            if grid[r][c] == bg:
                out[r][c] = 2
    for r in range(rmin, rmax + 1):
        for c in (cmin, cmax):
            if grid[r][c] == bg:
                out[r][c] = 2

    # Repair small breaks in any additional straight stroke, but do not join
    # opposite sides across the empty interior of the contour.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == mark]
        for a, b in zip(cols, cols[1:]):
            if 1 < b-a <= 3:
                for c in range(a+1, b):
                    if grid[r][c] == bg:
                        out[r][c] = 2
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == mark]
        for a, b in zip(rows, rows[1:]):
            if 1 < b-a <= 3:
                for r in range(a+1, b):
                    if grid[r][c] == bg:
                        out[r][c] = 2
    return out
